    if step == "week":
        monday = _add_days(d, -d.weekday())
        return Period(monday, _add_days(monday, 6))
    if step == "month":
        return _whole("month", d.year, d.month)
    if step == "quarter":
        return _whole("quarter", d.year, 3 * ((d.month - 1) // 3) + 1)
    return _whole("year", d.year, 1)


