"""Chart of accounts."""
import re

from tallybook.currency import CURRENCIES
from tallybook.dates import format_date, is_date
from tallybook.errors import NotFoundError, ValidationError
from tallybook.model import Account


class ChartError(ValidationError):
    pass


ROOT_TYPES = {
    "Assets": "asset",
    "Liabilities": "liability",
    "Equity": "equity",
    "Income": "income",
    "Expenses": "expense",
}
TYPES = tuple(ROOT_TYPES.values())

_SEGMENT = re.compile(r"[A-Z][A-Za-z0-9_-]*")


def valid_path(text):
    if not isinstance(text, str):
        return False
    parts = text.split(":")
    if parts[0] not in ROOT_TYPES:
        return False
    return all(_SEGMENT.fullmatch(p) is not None for p in parts)


def _need_path(path):
    if not valid_path(path):
        raise ChartError("invalid account path %r" % (path,))


def parent_path(path):
    _need_path(path)
    return path.rsplit(":", 1)[0] if ":" in path else None


def account_type(path):
    _need_path(path)
    return ROOT_TYPES[path.split(":", 1)[0]]


def _sort_key(path):
    return tuple(path.split(":"))


def _check_pattern(pattern):
    if not isinstance(pattern, str) or not pattern:
        raise ChartError("invalid account pattern %r" % (pattern,))
    parts = pattern.split(":")
    for p in parts:
        if p not in ("*", "**") and _SEGMENT.fullmatch(p) is None:
            raise ChartError("invalid account pattern %r" % (pattern,))
    return parts


def _match_segments(pat, segs):
    # pat: list of pattern segments, segs: list of path segments; exact match.
    if not pat:
        return not segs
    head = pat[0]
    if head == "**":
        for take in range(1, len(segs) + 1):
            if _match_segments(pat[1:], segs[take:]):
                return True
        return False
    if not segs:
        return False
    if head == "*" or head == segs[0]:
        return _match_segments(pat[1:], segs[1:])
    return False


def _pattern_matches(parts, path):
    segs = path.split(":")
    if all(p not in ("*", "**") for p in parts):
        return segs[: len(parts)] == parts
    return _match_segments(parts, segs)


def path_matches(pattern, path):
    parts = _check_pattern(pattern)
    if not isinstance(path, str):
        return False
    return _pattern_matches(parts, path)


class Chart:
    def __init__(self):
        self._accounts = {}
        self._explicit = set()

    def add(self, path, type=None, currency=None, opened=None, note=""):
        _need_path(path)
        root_type = account_type(path)
        if type is not None and (not isinstance(type, str) or type not in TYPES or type != root_type):
            raise ChartError("account type %r does not fit %s" % (type, path))
        if currency is not None and (not isinstance(currency, str) or currency not in CURRENCIES):
            raise ChartError("unknown currency %r" % (currency,))
        if opened is not None and not is_date(opened):
            raise ChartError("opened must be a date, got %r" % (opened,))
        if not isinstance(note, str):
            raise ChartError("note must be text, got %r" % (note,))
        if path in self._explicit:
            err = ChartError("account %s already exists" % path)
            err.code = "conflict"
            raise err
        existing = self._accounts.get(path)
        if existing is not None:
            existing.currency = currency
            existing.opened = opened
            existing.note = note
            account = existing
        else:
            account = Account(path, root_type, currency, opened, None, note)
            self._accounts[path] = account
        self._explicit.add(path)
        parent = parent_path(path)
        while parent is not None:
            if parent not in self._accounts:
                self._accounts[parent] = Account(parent, root_type)
            parent = parent_path(parent)
        return account

    def get(self, path):
        if not isinstance(path, str) or path not in self._accounts:
            raise NotFoundError("no such account: %s" % (path,))
        return self._accounts[path]

    def exists(self, path):
        return isinstance(path, str) and path in self._accounts

    __contains__ = exists

    def __len__(self):
        return len(self._accounts)

    def accounts(self):
        return [self._accounts[p] for p in sorted(self._accounts, key=_sort_key)]

    def is_explicit(self, path):
        return path in self._explicit

    def children(self, path):
        self.get(path)
        depth = path.count(":") + 1
        prefix = path + ":"
        return [a for a in self.accounts() if a.path.startswith(prefix) and a.path.count(":") == depth]

    def descendants(self, path):
        self.get(path)
        prefix = path + ":"
        return [a for a in self.accounts() if a.path.startswith(prefix)]

    def is_leaf(self, path):
        return not self.children(path)

    def is_open(self, path, on):
        account = self.get(path)
        if not is_date(on):
            raise ChartError("date must be a date, got %r" % (on,))
        return (account.opened is None or account.opened <= on) and (account.closed is None or on <= account.closed)

