            raise ChartError("close date must be a date, got %r" % (on,))
        if account.closed is not None:
            raise ChartError("account %s is already closed" % path)
        if account.opened is not None and on < account.opened:
            raise ChartError("cannot close %s on %s: before it opened on %s" % (path, format_date(on), format_date(account.opened)))
