from tallybook.money import Money, MoneyError
from tallybook.currency import CurrencyError


class ExportError(ValidationError):
    pass


def to_json(value):
    return json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


def _csv_field(value):
    text = "" if value is None else str(value)
    if any(ch in text for ch in ',"\r\n'):
        return '"' + text.replace('"', '""') + '"'
    return text


def to_csv(headers, rows):
    lines = [",".join(_csv_field(h) for h in headers)]
    for row in rows:
        lines.append(",".join(_csv_field(c) for c in row))
    return "".join(line + "\n" for line in lines)


_CSV_HEADER = ["id", "date", "flag", "payee", "narration", "tags", "account", "amount", "currency", "note"]


def transactions_to_csv(txs):
    rows = []
    for tx in txs:
        head = [
            "" if tx.id is None else str(tx.id),
            format_date(tx.date),
            tx.flag,
            tx.payee,
            tx.narration,
            ";".join(sorted(set(tx.tags))),
        ]
        if not tx.postings:
            rows.append(head + ["", "", "", ""])
        for p in tx.postings:
            if p.amount is None:
                rows.append(head + [p.account, "", "", p.note])
            else:
                rows.append(head + [p.account, p.amount.amount_str(), p.amount.currency, p.note])
    return to_csv(_CSV_HEADER, rows)


def money_to_dict(money):
    if money is None:
        return None
    return {"amount": money.amount_str(), "currency": money.currency}


def transaction_to_dict(tx):
    return {
        "id": tx.id,
        "date": format_date(tx.date),
        "flag": tx.flag,
        "payee": tx.payee,
        "narration": tx.narration,
        "tags": sorted(set(tx.tags)),
        "postings": [
            {"account": p.account, "amount": money_to_dict(p.amount), "note": p.note} for p in tx.postings
        ],
    }


def transactions_to_json(txs):
    return to_json([transaction_to_dict(tx) for tx in txs])


def _clean_cell(cell):
    text = "" if cell is None else str(cell)
    return text.replace("\t", " ").replace("\r", " ").replace("\n", " ")


def render_table(headers, rows, align=None):
    headers = [_clean_cell(h) for h in headers]
    if not headers:
        return ""
    n = len(headers)
    if align is None:
        letters = ["l"] * n
    else:
        if not isinstance(align, (str, list, tuple)):
            raise ExportError("align must be a string or a list of 'l'/'r'")
        letters = list(align)
        if len(letters) != n or any(a not in ("l", "r") for a in letters):
            raise ExportError("align must hold one 'l' or 'r' per column (%d columns)" % n)
    body = []
    for row in rows:
        cells = [_clean_cell(c) for c in row]
        if len(cells) != n:
            raise ExportError("row has %d cells, expected %d" % (len(cells), n))
        body.append(cells)
    widths = [max([len(headers[i])] + [len(r[i]) for r in body]) for i in range(n)]

    def line(cells):
        parts = [c.rjust(w) if a == "r" else c.ljust(w) for c, w, a in zip(cells, widths, letters)]
        return "  ".join(parts).rstrip(" ") + "\n"

    out = [line(headers), line(["-" * w for w in widths])]
    out.extend(line(r) for r in body)
    return "".join(out)


_TX_KEYS = {"id", "date", "flag", "payee", "narration", "tags", "postings"}
_POSTING_KEYS = {"account", "amount", "note"}


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _posting_from_obj(obj, where):
    if not isinstance(obj, dict):
        raise ExportError("%s: posting must be an object" % where)
    for key in obj:
        if key not in _POSTING_KEYS:
            raise ExportError("%s: unknown key %r" % (where, key))
    account = obj.get("account")
    if not isinstance(account, str):
        raise ExportError("%s: account is missing or not text" % where)
    note = obj.get("note", "")
    if not isinstance(note, str):
        raise ExportError("%s: note must be text" % where)
    amount = obj.get("amount")
    if amount is not None:
        if not isinstance(amount, dict) or set(amount) != {"amount", "currency"} or not all(
            isinstance(v, str) for v in amount.values()
        ):
            raise ExportError("%s: amount must be null or an object with text keys amount and currency" % where)
        try:
            amount = Money.of(amount["amount"], amount["currency"])
        except (MoneyError, CurrencyError) as exc:
            raise ExportError("%s: invalid amount: %s" % (where, exc.message)) from None
    return Posting(account, amount, note)


def _tx_from_obj(obj, index):
    where = "transaction %d" % index
    if not isinstance(obj, dict):
        raise ExportError("%s: must be an object" % where)
    for key in obj:
        if key not in _TX_KEYS:
            raise ExportError("%s: unknown key %r" % (where, key))
    for key in ("date", "payee", "postings"):
        if key not in obj:
            raise ExportError("%s: missing key %r" % (where, key))
    date_text = obj["date"]
    if not isinstance(date_text, str):
        raise ExportError("%s: date must be text YYYY-MM-DD" % where)
    try:
        when = parse_date(date_text)
    except DateError as exc:
        raise ExportError("%s: %s" % (where, exc.message)) from None
    tid = obj.get("id")
    if tid is not None and (not _is_int(tid) or tid < 1):
        raise ExportError("%s: id must be null or a whole number of at least 1" % where)
    flag = obj.get("flag", "*")
    if flag not in ("*", "!") or not isinstance(flag, str):
        raise ExportError("%s: flag must be '*' or '!'" % where)
    for key in ("payee", "narration"):
        if key in obj and not isinstance(obj[key], str):
            raise ExportError("%s: %s must be text" % (where, key))
    tags = obj.get("tags", [])
    if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
        raise ExportError("%s: tags must be a list of text" % where)
    postings_obj = obj["postings"]
    if not isinstance(postings_obj, list):
        raise ExportError("%s: postings must be a list" % where)
    postings = [_posting_from_obj(p, "%s posting %d" % (where, i)) for i, p in enumerate(postings_obj, 1)]
    return Transaction(
        when, obj["payee"], obj.get("narration", ""), postings, tuple(sorted(set(tags))), flag, tid
    )


def transactions_from_json(text):
    if not isinstance(text, (str, bytes)):
        raise ExportError("JSON text expected, got %r" % (text,))
    try:
        data = json.loads(text)
    except (ValueError, RecursionError) as exc:
        raise ExportError("not valid JSON: %s" % exc) from None
    if not isinstance(data, list):
        raise ExportError("JSON must be an array of transactions")
    return [_tx_from_obj(obj, i) for i, obj in enumerate(data, 1)]

