"""The `tallybook` command line: hand-written argument handling, thin layer on the library."""
import os
import sys
from datetime import date

from tallybook import __version__
from tallybook.dates import parse_date
from tallybook.errors import TallybookError


class UsageError(Exception):
    """The command line itself is wrong: exit status 2."""


class CliError(Exception):
    """A refusal: exit status 1. `lines` go to stderr, the first one prefixed by `tallybook: `."""

    def __init__(self, message, extra=()):
        super().__init__(message)
        self.message = message
        self.extra = list(extra)


class Stop(Exception):
    def __init__(self, text, code=0):
        self.text = text
        self.code = code


class Command:
    def __init__(self, name, usage, handler, pos=(), values=(), flags=(), repeat=(), required=(), rest=False):
        self.name = name
        self.usage = usage
        self.handler = handler
        self.pos = list(pos)  # names; a name ending in '?' is optional, '...' repeats
        self.values = set(values)
        self.flags = set(flags)
        self.repeat = set(repeat)
        self.required = set(required)


class Context:
    def __init__(self, db, today_opt):
        self.db = db
        self.today_opt = today_opt
        self.out = []

    def today(self):
        return self.today_opt if self.today_opt is not None else date.today()

    def write(self, text):
        self.out.append(text)

    def store(self):
        from tallybook.storage import Store

        return Store.open(self.db)


def _parse_command_args(cmd, args):
    values = cmd.values
    opts = {}
    pos = []
    i = 0
    n = len(args)
    while i < n:
        a = args[i]
        if a == "--":
            pos.extend(args[i + 1 :])
            break
        if a in ("-h", "--help"):
            raise Stop(cmd.usage)
        if a.startswith("--"):
            name, eq, val = a.partition("=")
            if name in cmd.flags:
                if eq:
                    raise UsageError("option %s takes no value" % name)
                if name in opts:
                    raise UsageError("option %s given twice" % name)
                opts[name] = True
            elif name in values:
                if eq:
                    v = val
                else:
                    if i + 1 >= n:
                        raise UsageError("option %s needs a value" % name)
                    i += 1
                    v = args[i]
                if name in cmd.repeat:
                    opts.setdefault(name, []).append(v)
                else:
                    if name in opts:
                        raise UsageError("option %s given twice" % name)
                    opts[name] = v
            else:
                raise UsageError("unknown option: %s" % name)
        elif a == "-p" and "--posting" in values:
            if i + 1 >= n:
                raise UsageError("option -p needs a value")
            i += 1
            opts.setdefault("--posting", []).append(args[i])
        else:
            pos.append(a)
        i += 1
    for name in sorted(cmd.required):
        if name not in opts:
            raise UsageError("missing required option %s" % name)
    required = [p for p in cmd.pos if not p.endswith("?") and not p.endswith("...")]
    variadic = any(p.endswith("...") for p in cmd.pos)
    optional = [p for p in cmd.pos if p.endswith("?")]
    if len(pos) < len(required):
        raise UsageError("missing argument: %s" % required[len(pos)])
    if not variadic and len(pos) > len(required) + len(optional):
        raise UsageError("unexpected argument: %s" % pos[len(required) + len(optional)])
    return pos, opts


def _resolve(tree, args, prefix):
    node = tree
    words = []
    i = 0
    while isinstance(node, dict):
        if i >= len(args) or args[i].startswith("-") and args[i] not in ("-h", "--help"):
            if i < len(args):
                raise UsageError("unknown option: %s" % args[i]) if args[i].startswith("--") else UsageError(
                    "missing subcommand for '%s'" % " ".join(words)
                )
            raise UsageError("missing subcommand for '%s'" % " ".join(words))
        word = args[i]
        if word in ("-h", "--help"):
            raise Stop(_group_usage(prefix + words, node))
        if word not in node:
            raise UsageError("unknown %s '%s'" % ("command" if not words else "word", word))
        node = node[word]
        words.append(word)
        i += 1
    return node, args[i:]


def _group_usage(words, node):
    lines = ["usage: tallybook %s WORD [ARGUMENTS]" % " ".join(words), "", "words:"]
    for name in node:
        lines.append("  " + name)
    return "\n".join(lines) + "\n"


def _main_usage(tree):
    lines = [
        "usage: tallybook [--db FILE] [--today DATE] COMMAND [WORD] [ARGUMENTS and --options]",
        "",
        "global options:",
        "  --db FILE      the book file (default: $TALLYBOOK_DB, else tallybook.db)",
        "  --today DATE   what today is (default: the real date)",
        "  --version      print the version and stop",
        "  -h, --help     print this help and stop",
        "",
        "commands:",
    ]
    for name in tree:
        lines.append("  " + name)
    return "\n".join(lines) + "\n"


def _write_out(text):
    stream = sys.stdout
    buf = getattr(stream, "buffer", None)
    if buf is not None:
        buf.write(text.encode("utf-8"))
        buf.flush()
    else:
        stream.write(text)
        stream.flush()


def _write_err(text):
    stream = sys.stderr
    try:
        buf = getattr(stream, "buffer", None)
        if buf is not None:
            buf.write(text.encode("utf-8", "replace"))
            buf.flush()
        else:
            stream.write(text)
            stream.flush()
    except (OSError, ValueError):
        pass


def _silence_stdout():
    try:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
    except (OSError, ValueError, AttributeError):
        pass


def _emit(ctx, code):
    text = "".join(ctx.out)
    if not text:
        return code
    try:
        _write_out(text)
    except BrokenPipeError:
        _silence_stdout()
        return 0
    except OSError as exc:
        _write_err("tallybook: cannot write output: %s\n" % (exc.strerror or exc))
        return 1
    return code


def _fail(err_lines):
    _write_err("".join(line + "\n" for line in err_lines))


def main(argv=None):
    from tallybook.cli.commands import build_tree

    args = list(sys.argv[1:] if argv is None else argv)
    tree = build_tree()
    db = None
    today_opt = None
    seen = set()
    i = 0
    try:
        while i < len(args):
            a = args[i]
            if a == "--version":
                _write_out("tallybook %s\n" % __version__)
                return 0
            if a in ("-h", "--help"):
                _write_out(_main_usage(tree))
                return 0
            if a.startswith("--") and a.split("=", 1)[0] in ("--db", "--today"):
                name, eq, val = a.partition("=")
                if name in seen:
                    raise UsageError("option %s given twice" % name)
                seen.add(name)
                if eq:
                    v = val
                else:
                    if i + 1 >= len(args):
                        raise UsageError("option %s needs a value" % name)
                    i += 1
                    v = args[i]
                if name == "--db":
                    db = v
                else:
                    try:
                        today_opt = parse_date(v)
                    except TallybookError as exc:
                        raise CliError(exc.message) from None
                i += 1
                continue
            break
        rest = args[i:]
        if not rest:
            raise UsageError("no command given")
        if rest[0].startswith("-"):
            raise UsageError("unknown option: %s" % rest[0].split("=", 1)[0])
        if db is None:
            db = os.environ.get("TALLYBOOK_DB") or "tallybook.db"
        cmd, cmd_args = _resolve(tree, rest, [])
        pos, opts = _parse_command_args(cmd, cmd_args)
        ctx = Context(db, today_opt)
        code = cmd.handler(ctx, pos, opts)
        return _emit(ctx, code or 0)
    except Stop as stop:
        try:
            _write_out(stop.text)
        except BrokenPipeError:
            _silence_stdout()
        return stop.code
    except UsageError as exc:
        _fail(["tallybook: %s" % exc, "Try 'tallybook --help'."])
        return 2
    except CliError as exc:
        _fail(["tallybook: %s" % exc.message] + exc.extra)
        return 1
    except TallybookError as exc:
        _fail(["tallybook: %s" % exc.message])
        return 1
    except BrokenPipeError:
        _silence_stdout()
        return 0
    except KeyboardInterrupt:
        return 130
    except (RecursionError, MemoryError, OSError, UnicodeError, ValueError, ArithmeticError) as exc:
        _fail(["tallybook: %s" % (exc or type(exc).__name__)])
        return 1
    except Exception as exc:  # never a traceback
        _fail(["tallybook: internal error: %s: %s" % (type(exc).__name__, exc)])
        return 1


if __name__ == "__main__":
    sys.exit(main())

