"""Command handlers and the command table of the `tallybook` command line."""
import os
import re
import sys
from datetime import date, timedelta

from tallybook import budgets as budgets_mod
from tallybook import recurring as recurring_mod
from tallybook import reports
from tallybook.accounts import account_type, parent_path, path_matches, valid_path
from tallybook.cli.main import CliError, Command, UsageError
from tallybook.csvimport import import_csv as csv_import, parse_profile
from tallybook.currency import RateTable
from tallybook.dates import Period, add_months, format_date, last_day, parse_date, periods
from tallybook.errors import TallybookError, ValidationError
from tallybook.export import (
    money_to_dict,
    render_table,
    to_json,
    transaction_to_dict,
    transactions_to_csv,
    transactions_to_json,
)
from tallybook.journal import Journal, JournalError, format_journal, format_transaction, parse_journal
from tallybook.model import Posting, Transaction
from tallybook.money import Money, format_minor
from tallybook.query import parse_query, select
from tallybook.rules import parse_rules

_WHOLE = re.compile(r"(-?)([0-9]{1,18})")
_WEEKDAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]


# -- value helpers -----------------------------------------------------------


def whole(text, what, negative=False):
    m = _WHOLE.fullmatch(text)
    if m is None or (m.group(1) and not negative):
        raise CliError("invalid %s %r: expected a whole number" % (what, text))
    return int(text)


def lib_date(text):
    return parse_date(text)


def read_text(name):
    if name == "-":
        label = "standard input"
        try:
            stream = getattr(sys.stdin, "buffer", None)
            data = stream.read() if stream is not None else sys.stdin.read()
        except OSError as exc:
            raise CliError("cannot read %s: %s" % (label, exc.strerror or exc)) from None
    else:
        label = name
        try:
            with open(name, "rb") as handle:
                data = handle.read()
        except OSError as exc:
            raise CliError("cannot read %s: %s" % (name, exc.strerror or exc)) from None
    if isinstance(data, str):
        return data
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise CliError("%s is not valid UTF-8 text" % label) from None


def journal_from(name):
    text = read_text(name)
    try:
        return parse_journal(text)
    except JournalError as exc:
        raise CliError("%s: %s" % ("standard input" if name == "-" else name, exc.message)) from None


def parse_posting(text):
    head, semi, note = text.partition(";")
    parts = re.split(r"[ \t]+", head.strip(" \t"))
    if semi:
        note = note.strip(" \t")
    if len(parts) == 1 and parts[0]:
        return Posting(parts[0], None, note)
    if len(parts) == 3:
        return Posting(parts[0], Money.of(parts[1], parts[2]), note)
    raise CliError("invalid posting %r: expected ACCOUNT or ACCOUNT AMOUNT CURRENCY, then an optional ; note" % text)


def build_template(opts, pos_payee, when):
    postings = [parse_posting(p) for p in opts.get("--posting", [])]
    return Transaction(
        when,
        pos_payee,
        opts.get("--narration", ""),
        postings,
        tuple(opts.get("--tag", [])),
        opts.get("--flag", "*"),
    )


def tx_table(txs):
    if not txs:
        return ""
    rows = [
        [t.id, format_date(t.date), t.flag, t.payee, t.narration, " ".join("#" + g for g in sorted(set(t.tags)))]
        for t in txs
    ]
    return render_table(["Id", "Date", "Flag", "Payee", "Narration", "Tags"], rows, "rlllll")


def account_dict(a):
    return {
        "path": a.path,
        "type": a.type,
        "currency": a.currency,
        "opened": None if a.opened is None else format_date(a.opened),
        "closed": None if a.closed is None else format_date(a.closed),
        "note": a.note,
    }


def month_of(day):
    return Period(day.replace(day=1), day.replace(day=last_day(day.year, day.month)))


# -- init, db, serve ---------------------------------------------------------


def cmd_init(ctx, pos, opts):
    from tallybook.storage import LATEST_VERSION, Store

    fresh = not os.path.exists(ctx.db) or (os.path.isfile(ctx.db) and os.path.getsize(ctx.db) == 0)
    with Store.open(ctx.db, create=True) as store:
        if fresh:
            ctx.write("created %s (version %d)\n" % (ctx.db, store.version))
            return 0
        old = store.version
        if old < LATEST_VERSION:
            store.migrate()
            ctx.write("migrated %s from version %d to %d\n" % (ctx.db, old, store.version))
        else:
            ctx.write("%s is up to date (version %d)\n" % (ctx.db, old))
    return 0


def cmd_db_version(ctx, pos, opts):
    with ctx.store() as store:
        ctx.write("%d\n" % store.version)


def cmd_db_migrate(ctx, pos, opts):
    from tallybook.storage import LATEST_VERSION

    with ctx.store() as store:
        applied = store.migrate()
        if applied:
            for v in applied:
                ctx.write("applied version %d\n" % v)
        else:
            ctx.write("database is up to date (version %d)\n" % LATEST_VERSION)


def cmd_db_info(ctx, pos, opts):
    with ctx.store() as store:
        info = store.info()
    if opts.get("--json"):
        ctx.write(to_json(info))
        return
    for key in ("path", "version", "accounts", "transactions", "postings", "rates", "budgets", "recurring"):
        ctx.write("%s: %s\n" % (key, info[key]))


def cmd_db_check(ctx, pos, opts):
    with ctx.store() as store:
        problems = store.check()
    if not problems:
        ctx.write("ok\n")
        return 0
    ctx.write("".join(p + "\n" for p in problems))
    return 1


def cmd_db_backup(ctx, pos, opts):
    with ctx.store() as store:
        store.backup(pos[0])
    ctx.write("backed up to %s\n" % pos[0])


def cmd_serve(ctx, pos, opts):
    from tallybook.api.server import serve

    host = opts.get("--host", "127.0.0.1")
    port = whole(opts["--port"], "port") if "--port" in opts else 8765
    if port > 65535:
        raise CliError("invalid port %r: the largest is 65535" % opts["--port"])
    with ctx.store() as store:
        store.info()
    return serve(ctx.db, host=host, port=port, today=ctx.today_opt)


# -- accounts ----------------------------------------------------------------


def cmd_account_add(ctx, pos, opts):
    opened = lib_date(opts["--open"]) if "--open" in opts else None
    with ctx.store() as store:
        store.add_account(pos[0], None, opts.get("--currency"), opened, opts.get("--note", ""))
    ctx.write("added account %s\n" % pos[0])


def cmd_account_list(ctx, pos, opts):
    with ctx.store() as store:
        accounts = store.accounts(
            opts.get("--type"), opts.get("--under"), opts.get("--currency"), include_closed=not opts.get("--open-only")
        )
    if opts.get("--json"):
        ctx.write(to_json([account_dict(a) for a in accounts]))
    elif accounts:
        rows = [
            [
                a.path,
                a.type,
                a.currency or "",
                "" if a.opened is None else format_date(a.opened),
                "" if a.closed is None else format_date(a.closed),
                a.note,
            ]
            for a in accounts
        ]
        ctx.write(render_table(["Account", "Type", "Currency", "Opened", "Closed", "Note"], rows))


def cmd_account_show(ctx, pos, opts):
    with ctx.store() as store:
        account = store.get_account(pos[0])
        balance = store.ledger().balance(pos[0])
    money = [balance[c] for c in sorted(balance)]
    if opts.get("--json"):
        data = account_dict(account)
        data["balance"] = [money_to_dict(m) for m in money]
        ctx.write(to_json(data))
        return
    d = account_dict(account)
    lines = [
        "path: %s" % account.path,
        "type: %s" % account.type,
        "currency: %s" % (account.currency or "any"),
        "opened: %s" % (d["opened"] or "none"),
        "closed: %s" % (d["closed"] or "none"),
        ("note: %s" % account.note) if account.note else "note:",
        "balance: %s" % (", ".join(str(m) for m in money) if money else "none"),
    ]
    ctx.write("".join(line + "\n" for line in lines))


def cmd_account_close(ctx, pos, opts):
    on = lib_date(opts["--on"]) if "--on" in opts else ctx.today()
    with ctx.store() as store:
        store.close_account(pos[0], on)
    ctx.write("closed account %s on %s\n" % (pos[0], format_date(on)))


# -- transactions ------------------------------------------------------------


def cmd_tx_add(ctx, pos, opts):
    when = lib_date(opts["--date"]) if "--date" in opts else ctx.today()
    tx = build_template(opts, pos[0], when)
    with ctx.store() as store:
        stored = store.add_transaction(tx)
    if opts.get("--json"):
        ctx.write(to_json(transaction_to_dict(stored)))
    else:
        ctx.write("added transaction %d\n" % stored.id)


def _listing(ctx, txs, opts):
    if opts.get("--json"):
        ctx.write(to_json([transaction_to_dict(t) for t in txs]))
    else:
        ctx.write(tx_table(txs))


def _paging(opts):
    limit = whole(opts["--limit"], "limit") if "--limit" in opts else None
    offset = whole(opts["--offset"], "offset") if "--offset" in opts else 0
    return limit, offset


def cmd_tx_list(ctx, pos, opts):
    limit, offset = _paging(opts)
    with ctx.store() as store:
        txs = store.transactions(opts.get("--query"), limit, offset)
    _listing(ctx, txs, opts)


def cmd_query(ctx, pos, opts):
    limit, offset = _paging(opts)
    with ctx.store() as store:
        if opts.get("--count"):
            ctx.write("%d\n" % store.count_transactions(pos[0]))
            return
        txs = store.transactions(pos[0], limit, offset)
    _listing(ctx, txs, opts)


def cmd_tx_show(ctx, pos, opts):
    tid = whole(pos[0], "transaction id")
    with ctx.store() as store:
        tx = store.get_transaction(tid)
    if opts.get("--json"):
        ctx.write(to_json(transaction_to_dict(tx)))
    else:
        ctx.write("; id %d\n" % tx.id + format_transaction(tx))


def cmd_tx_delete(ctx, pos, opts):
    tid = whole(pos[0], "transaction id")
    with ctx.store() as store:
        store.delete_transaction(tid)
    ctx.write("deleted transaction %d\n" % tid)


def cmd_export(ctx, pos, opts):
    fmt = opts.get("--format", "csv")
    if fmt not in ("csv", "json", "journal"):
        raise CliError("unknown export format %r: expected csv, json or journal" % fmt)
    if fmt == "journal" and "--query" in opts:
        raise CliError("export --format journal exports the whole book and takes no --query")
    with ctx.store() as store:
        if fmt == "journal":
            ctx.write(format_journal(store.journal()))
        elif fmt == "csv":
            ctx.write(transactions_to_csv(store.transactions(opts.get("--query"))))
        else:
            ctx.write(transactions_to_json(store.transactions(opts.get("--query"))))


def cmd_journal_export(ctx, pos, opts):
    with ctx.store() as store:
        ctx.write(format_journal(store.journal()))


def cmd_journal_import(ctx, pos, opts):
    journal = journal_from(pos[0])
    with ctx.store() as store:
        store.load_journal(journal)
    ctx.write(
        "imported %d accounts, %d rates, %d transactions\n"
        % (len(journal.accounts), len(journal.rates), len(journal.transactions))
    )


# -- bank statements, profiles, rules ---------------------------------------


def cmd_import(ctx, pos, opts):
    if ("--profile" in opts) == ("--profile-file" in opts):
        raise UsageError("give exactly one of --profile and --profile-file")
    text = read_text(pos[0])
    if "--profile-file" in opts:
        profile = parse_profile(read_text(opts["--profile-file"]))
    with ctx.store() as store:
        if "--profile" in opts:
            profile = parse_profile(store.profile_text(opts["--profile"]))
        outcome = store.import_csv(text, profile, apply_rules=not opts.get("--no-rules"))
    if outcome.errors:
        raise CliError(
            "%d rows could not be imported, nothing was imported" % len(outcome.errors),
            ["row %d: %s" % (n, msg) for n, msg in outcome.errors],
        )
    ctx.write("imported %d transactions, %d duplicates\n" % (len(outcome.added), len(outcome.duplicates)))


def cmd_profile_add(ctx, pos, opts):
    text = read_text(pos[1])
    with ctx.store() as store:
        store.set_profile(pos[0], text)
    ctx.write("stored profile %s\n" % pos[0])


def cmd_profile_list(ctx, pos, opts):
    with ctx.store() as store:
        names = store.profiles()
    if opts.get("--json"):
        ctx.write(to_json(names))
    else:
        ctx.write("".join(n + "\n" for n in names))


def cmd_profile_show(ctx, pos, opts):
    with ctx.store() as store:
        text = store.profile_text(pos[0])
    ctx.write(text if text.endswith("\n") or text == "" else text + "\n")


def cmd_profile_remove(ctx, pos, opts):
    with ctx.store() as store:
        store.remove_profile(pos[0])
    ctx.write("removed profile %s\n" % pos[0])


def cmd_rules_set(ctx, pos, opts):
    text = read_text(pos[0])
    count = len(parse_rules(text))
    with ctx.store() as store:
        store.set_rules(text)
    ctx.write("stored %d rules\n" % count)


def cmd_rules_show(ctx, pos, opts):
    with ctx.store() as store:
        text = store.rules_text()
    if text:
        ctx.write(text if text.endswith("\n") else text + "\n")


# -- rates, budgets, recurring ----------------------------------------------


def cmd_rate_set(ctx, pos, opts):
    on = lib_date(opts["--on"]) if "--on" in opts else ctx.today()
    with ctx.store() as store:
        store.set_rate(pos[0], pos[1], pos[2], on)
    ctx.write("set 1 %s = %s %s on %s\n" % (pos[0], pos[2], pos[1], format_date(on)))


def cmd_rate_list(ctx, pos, opts):
    with ctx.store() as store:
        rows = store.rate_rows()
    if opts.get("--json"):
        ctx.write(
            to_json([{"from": s, "to": d, "date": format_date(o), "rate": t} for s, d, o, t in rows])
        )
    elif rows:
        ctx.write(render_table(["From", "To", "Date", "Rate"], [[s, d, format_date(o), t] for s, d, o, t in rows], "lllr"))


def cmd_rate_remove(ctx, pos, opts):
    on = lib_date(opts["--on"]) if "--on" in opts else ctx.today()
    with ctx.store() as store:
        store.remove_rate(pos[0], pos[1], on)
    ctx.write("removed rate %s -> %s on %s\n" % (pos[0], pos[1], format_date(on)))


def cmd_budget_add(ctx, pos, opts):
    start = lib_date(opts["--start"]) if "--start" in opts else ctx.today()
    kind = opts.get("--per", "month")
    budget = budgets_mod.Budget(pos[0], kind, Money.parse(pos[1]), start)
    with ctx.store() as store:
        store.add_budget(budget)
    ctx.write("added budget %s %s per %s\n" % (budget.pattern, budget.amount, budget.period_kind))


def cmd_budget_list(ctx, pos, opts):
    with ctx.store() as store:
        items = store.budgets()
    if opts.get("--json"):
        ctx.write(
            to_json(
                [
                    {
                        "pattern": b.pattern,
                        "period_kind": b.period_kind,
                        "amount": money_to_dict(b.amount),
                        "start": format_date(b.start),
                    }
                    for b in items
                ]
            )
        )
    elif items:
        rows = [[b.pattern, b.period_kind, str(b.amount), format_date(b.start)] for b in items]
        ctx.write(render_table(["Pattern", "Per", "Amount", "Start"], rows, "llrl"))


def cmd_budget_remove(ctx, pos, opts):
    kind = opts.get("--per", "month")
    with ctx.store() as store:
        store.remove_budget(pos[0], kind)
    ctx.write("removed budget %s per %s\n" % (pos[0], kind))


def status_output(ctx, lines, as_json):
    if as_json:
        ctx.write(to_json([line.to_dict() for line in lines]))
    elif lines:
        rows = [
            [
                ln.pattern,
                ln.period_kind,
                str(ln.budget),
                str(ln.actual),
                str(ln.remaining),
                "%s%%" % ln.percent,
                "over" if ln.over else "",
            ]
            for ln in lines
        ]
        ctx.write(
            render_table(["Pattern", "Per", "Budget", "Actual", "Remaining", "Percent", "Over"], rows, "llrrrrl")
        )


def cmd_budget_status(ctx, pos, opts):
    period = Period.parse(opts["--period"]) if "--period" in opts else month_of(ctx.today())
    with ctx.store() as store:
        lines = budgets_mod.budget_status(store.budgets(), store.ledger(), period)
    status_output(ctx, lines, opts.get("--json"))


def cmd_recurring_add(ctx, pos, opts):
    start = lib_date(opts["--start"]) if "--start" in opts else ctx.today()
    end = lib_date(opts["--end"]) if "--end" in opts else None
    count = whole(opts["--count"], "count") if "--count" in opts else None
    template = build_template(opts, pos[2], start)
    rec = recurring_mod.Recurring(pos[0], pos[1], template, start, end, count)
    with ctx.store() as store:
        store.add_recurring(rec)
    ctx.write("added recurring %s\n" % pos[0])


def _recurring_dict(rec, through):
    t = rec.template
    return {
        "name": rec.name,
        "schedule": str(rec.schedule),
        "start": format_date(rec.start),
        "end": None if rec.end is None else format_date(rec.end),
        "count": rec.count,
        "materialized_through": None if through is None else format_date(through),
        "template": {
            "payee": t.payee,
            "narration": t.narration,
            "flag": t.flag,
            "tags": sorted(set(t.tags)),
            "postings": [
                {"account": p.account, "amount": money_to_dict(p.amount), "note": p.note} for p in t.postings
            ],
        },
    }


def cmd_recurring_list(ctx, pos, opts):
    with ctx.store() as store:
        items = [(rec, store.materialized_through(rec.name)) for rec in store.recurring()]
    if opts.get("--json"):
        ctx.write(to_json([_recurring_dict(r, t) for r, t in items]))
    elif items:
        rows = [
            [
                r.name,
                str(r.schedule),
                format_date(r.start),
                "" if r.end is None else format_date(r.end),
                "" if r.count is None else r.count,
                "" if t is None else format_date(t),
                r.template.payee,
            ]
            for r, t in items
        ]
        ctx.write(render_table(["Name", "Schedule", "Start", "End", "Count", "Through", "Payee"], rows))


def cmd_recurring_remove(ctx, pos, opts):
    with ctx.store() as store:
        store.remove_recurring(pos[0])
    ctx.write("removed recurring %s\n" % pos[0])


def cmd_recurring_materialize(ctx, pos, opts):
    upto = lib_date(opts["--upto"]) if "--upto" in opts else None
    with ctx.store() as store:
        made = store.materialize(upto, ctx.today())
    if opts.get("--json"):
        ctx.write(to_json([transaction_to_dict(t) for t in made]))
    else:
        ctx.write("created %d transactions\n" % len(made))


# -- reports -----------------------------------------------------------------


def run_report(ctx, kind, ledger, account, opts):
    today = ctx.today()
    if kind == "trial-balance":
        as_of = lib_date(opts["--as-of"]) if "--as-of" in opts else None
        report = reports.trial_balance(ledger, as_of)
    elif kind == "balance-sheet":
        as_of = lib_date(opts["--as-of"]) if "--as-of" in opts else today
        report = reports.balance_sheet(ledger, as_of, opts.get("--convert"), today)
    elif kind == "income-statement":
        period = Period.parse(opts["--period"]) if "--period" in opts else month_of(today)
        report = reports.income_statement(ledger, period, opts.get("--convert"))
    elif kind == "cashflow":
        period = Period.parse(opts["--period"]) if "--period" in opts else month_of(today)
        report = reports.cashflow(ledger, period)
    else:
        period = Period.parse(opts["--period"]) if "--period" in opts else None
        report = reports.register(ledger, account, period, bool(opts.get("--rollup")))
    if opts.get("--json"):
        ctx.write(to_json(report))
    else:
        ctx.write(reports.render_text(report))


def make_report_cmd(kind):
    def handler(ctx, pos, opts):
        with ctx.store() as store:
            ledger = store.ledger()
        run_report(ctx, kind, ledger, pos[0] if pos else None, opts)

    return handler


# -- calc --------------------------------------------------------------------


def cmd_calc_money_parse(ctx, pos, opts):
    m = Money.parse(pos[0])
    ctx.write("%d %s\n" % (m.minor, m.currency))


def cmd_calc_money_format(ctx, pos, opts):
    minor = whole(pos[0], "minor units", negative=True)
    ctx.write("%s %s\n" % (format_minor(minor, pos[1]), pos[1]))


def cmd_calc_money_add(ctx, pos, opts):
    ctx.write("%s\n" % (Money.parse(pos[0]) + Money.parse(pos[1])))


def cmd_calc_money_sub(ctx, pos, opts):
    ctx.write("%s\n" % (Money.parse(pos[0]) - Money.parse(pos[1])))


def cmd_calc_money_scale(ctx, pos, opts):
    m = re.fullmatch(r"(-?[0-9]{1,18})(?:/(-?[0-9]{1,18}))?", pos[1])
    if m is None:
        raise CliError("invalid ratio %r: expected N or N/D with whole numbers" % pos[1])
    num = int(m.group(1))
    den = int(m.group(2)) if m.group(2) is not None else 1
    ctx.write("%s\n" % Money.parse(pos[0]).scale(num, den))


def cmd_calc_money_allocate(ctx, pos, opts):
    weights = [whole(w, "weight") for w in pos[1:]]
    for part in Money.parse(pos[0]).allocate(weights):
        ctx.write("%s\n" % part)


def cmd_calc_money_convert(ctx, pos, opts):
    m = Money.parse(pos[0])
    table = RateTable()
    day = date(2000, 1, 1)
    table.set(m.currency, pos[1], pos[2], day)
    ctx.write("%s\n" % table.convert(m, pos[1], day))


def cmd_calc_date_parse(ctx, pos, opts):
    d = lib_date(pos[0])
    ctx.write("%s %s\n" % (format_date(d), _WEEKDAYS[d.weekday()]))


def cmd_calc_date_add_months(ctx, pos, opts):
    n = whole(pos[1], "number of months", negative=True)
    ctx.write("%s\n" % format_date(add_months(lib_date(pos[0]), n)))


def cmd_calc_date_period(ctx, pos, opts):
    p = Period.parse(pos[0])
    nxt = p.next()
    ctx.write(
        "start: %s\nend: %s\ndays: %d\nlabel: %s\nnext: %s\n"
        % (format_date(p.start), format_date(p.end), p.days, p.label, nxt.label)
    )


def cmd_calc_date_periods(ctx, pos, opts):
    start, end = lib_date(pos[0]), lib_date(pos[1])
    step = pos[2]
    unit = {"week": 7, "month": 31, "quarter": 92, "year": 366}.get(step)
    if unit is not None and end >= start and (end - start).days // unit > 5000:
        raise CliError("too many periods (more than 5000)")
    result = periods(start, end, step)
    if len(result) > 5000:
        raise CliError("too many periods (more than 5000)")
    ctx.write("".join(p.label + "\n" for p in result))


def cmd_calc_schedule(ctx, pos, opts):
    frm, to = lib_date(opts["--from"]), lib_date(opts["--to"])
    start = lib_date(opts["--start"]) if "--start" in opts else frm
    end = lib_date(opts["--end"]) if "--end" in opts else None
    count = whole(opts["--count"], "count") if "--count" in opts else None
    if (to - min(frm, start)).days > 40000:
        raise CliError("the span to examine is longer than 40000 days")
    template = Transaction(start, "calc", "", [], (), "*", None)
    rec = recurring_mod.Recurring("calc", pos[0], template, start, end, count)
    ctx.write("".join(format_date(d) + "\n" for d in recurring_mod.occurrences(rec, frm, to)))


def cmd_calc_account_check(ctx, pos, opts):
    path = pos[0]
    kind = account_type(path)
    parent = parent_path(path)
    ctx.write("path: %s\ntype: %s\nparent: %s\n" % (path, kind, parent if parent is not None else "none"))


def cmd_calc_account_match(ctx, pos, opts):
    ctx.write("yes\n" if path_matches(pos[0], pos[1]) else "no\n")


def cmd_calc_rules(ctx, pos, opts):
    rules = parse_rules(read_text(pos[0]))
    fields = {}
    if "--payee" in opts:
        fields["payee"] = opts["--payee"]
    if "--narration" in opts:
        fields["narration"] = opts["--narration"]
    if "--amount" in opts:
        fields["amount"] = Money.parse(opts["--amount"])
    if "--date" in opts:
        fields["date"] = lib_date(opts["--date"])
    rule = rules.match(fields)
    if rule is None:
        ctx.write("no match\n")
        return
    result = rules.apply(fields)
    ctx.write("rule: %d\n" % rule.line)
    for key in ("account", "payee", "narration", "flag"):
        if key in result:
            ctx.write(("%s: %s\n" % (key, result[key])) if result[key] else "%s:\n" % key)
    if "tags" in result:
        ctx.write("tags: %s\n" % ",".join(result["tags"]))


def cmd_calc_journal_check(ctx, pos, opts):
    journal = journal_from(pos[0])
    journal.to_ledger()
    ctx.write(
        "ok: %d accounts, %d rates, %d transactions\n"
        % (len(journal.accounts), len(journal.rates), len(journal.transactions))
    )


def cmd_calc_journal_format(ctx, pos, opts):
    ctx.write(format_journal(journal_from(pos[0])))


def journal_ledger(name):
    return journal_from(name).to_ledger()


def cmd_calc_query(ctx, pos, opts):
    ledger = journal_ledger(opts["--journal"])
    q = parse_query(pos[0], ledger.chart)
    txs = select(ledger.transactions(), q)
    _listing(ctx, txs, opts)


def cmd_calc_rate(ctx, pos, opts):
    ledger = journal_ledger(opts["--journal"])
    rate = ledger.rates.rate(pos[0], pos[1], lib_date(opts["--on"]))
    ctx.write("%d/%d\n" % (rate.numerator, rate.denominator))


def cmd_calc_budget(ctx, pos, opts):
    ledger = journal_ledger(opts["--journal"])
    period = Period.parse(opts["--period"])
    start = lib_date(opts["--start"]) if "--start" in opts else period.start
    budget = budgets_mod.Budget(pos[0], opts.get("--per", "month"), Money.parse(pos[1]), start)
    status_output(ctx, budgets_mod.budget_status([budget], ledger, period), opts.get("--json"))


_REPORT_KINDS = ("trial-balance", "balance-sheet", "income-statement", "cashflow", "register")


def cmd_calc_report(ctx, pos, opts):
    kind = pos[0]
    if kind not in _REPORT_KINDS:
        raise UsageError("unknown report kind '%s'" % kind)
    account = pos[1] if len(pos) > 1 else None
    if kind == "register" and account is None:
        raise UsageError("missing argument: ACCOUNT")
    ledger = journal_ledger(opts["--journal"])
    run_report(ctx, kind, ledger, account, opts)


def cmd_calc_csv(ctx, pos, opts):
    profile = parse_profile(read_text(pos[0]))
    rules = parse_rules(read_text(opts["--rules"])) if "--rules" in opts else None
    result = csv_import(read_text(pos[1]), profile, rules, ())
    if result.errors:
        raise CliError_lines(["row %d: %s" % (n, msg) for n, msg in result.errors])
    ctx.write(format_journal(Journal([], [], result.transactions)))


class CliError_lines(CliError):
    """A refusal whose stderr is exactly the given lines, without the `tallybook: ` lead."""

    def __init__(self, lines):
        super().__init__(lines[0], lines[1:])


