"""Command handlers and the command table of the `tallybook` command line."""
import os
import re
import sys
from datetime import date, timedelta

from tallybook import budgets as budgets_mod
from tallybook import recurring as recurring_mod
from tallybook import reports
from tallybook.accounts import account_type, parent_path, path_matches, valid_path
from tallybook.cli.main import CliError, Command, UsageError
from tallybook.csvimport import import_csv as csv_import, parse_profile
from tallybook.currency import RateTable
from tallybook.dates import Period, add_months, format_date, last_day, parse_date, periods
from tallybook.errors import TallybookError, ValidationError
from tallybook.export import (
    money_to_dict,
    render_table,
    to_json,
    transaction_to_dict,
    transactions_to_csv,
    transactions_to_json,
)
from tallybook.journal import Journal, JournalError, format_journal, format_transaction, parse_journal
from tallybook.model import Posting, Transaction
from tallybook.money import Money, format_minor
from tallybook.query import parse_query, select
from tallybook.rules import parse_rules

_WHOLE = re.compile(r"(-?)([0-9]{1,18})")
_WEEKDAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]


# -- value helpers -----------------------------------------------------------


def whole(text, what, negative=False):
    m = _WHOLE.fullmatch(text)
    if m is None or (m.group(1) and not negative):
        raise CliError("invalid %s %r: expected a whole number" % (what, text))
    return int(text)


def lib_date(text):
    return parse_date(text)


def read_text(name):
    if name == "-":
        label = "standard input"
        try:
            stream = getattr(sys.stdin, "buffer", None)
            data = stream.read() if stream is not None else sys.stdin.read()
        except OSError as exc:
            raise CliError("cannot read %s: %s" % (label, exc.strerror or exc)) from None
    else:
        label = name
        try:
            with open(name, "rb") as handle:
                data = handle.read()
        except OSError as exc:
            raise CliError("cannot read %s: %s" % (name, exc.strerror or exc)) from None
    if isinstance(data, str):
        return data
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise CliError("%s is not valid UTF-8 text" % label) from None


def journal_from(name):
    text = read_text(name)
    try:
        return parse_journal(text)
    except JournalError as exc:
        raise CliError("%s: %s" % ("standard input" if name == "-" else name, exc.message)) from None


def parse_posting(text):
    head, semi, note = text.partition(";")
    parts = re.split(r"[ \t]+", head.strip(" \t"))
    if semi:
        note = note.strip(" \t")
    if len(parts) == 1 and parts[0]:
        return Posting(parts[0], None, note)
    if len(parts) == 3:
        return Posting(parts[0], Money.of(parts[1], parts[2]), note)
    raise CliError("invalid posting %r: expected ACCOUNT or ACCOUNT AMOUNT CURRENCY, then an optional ; note" % text)


def build_template(opts, pos_payee, when):
    postings = [parse_posting(p) for p in opts.get("--posting", [])]
    return Transaction(
        when,
        pos_payee,
        opts.get("--narration", ""),
        postings,
        tuple(opts.get("--tag", [])),
        opts.get("--flag", "*"),
    )


def tx_table(txs):
    if not txs:
        return ""
    rows = [
        [t.id, format_date(t.date), t.flag, t.payee, t.narration, " ".join("#" + g for g in sorted(set(t.tags)))]
        for t in txs
    ]
    return render_table(["Id", "Date", "Flag", "Payee", "Narration", "Tags"], rows, "rlllll")


def account_dict(a):
    return {
        "path": a.path,
        "type": a.type,
        "currency": a.currency,
        "opened": None if a.opened is None else format_date(a.opened),
        "closed": None if a.closed is None else format_date(a.closed),
        "note": a.note,
    }


def month_of(day):
    return Period(day.replace(day=1), day.replace(day=last_day(day.year, day.month)))


# -- init, db, serve ---------------------------------------------------------


def cmd_init(ctx, pos, opts):
    from tallybook.storage import LATEST_VERSION, Store

    fresh = not os.path.exists(ctx.db) or (os.path.isfile(ctx.db) and os.path.getsize(ctx.db) == 0)
    with Store.open(ctx.db, create=True) as store:
        if fresh:
            ctx.write("created %s (version %d)\n" % (ctx.db, store.version))
            return 0
        old = store.version
        if old < LATEST_VERSION:
            store.migrate()
            ctx.write("migrated %s from version %d to %d\n" % (ctx.db, old, store.version))
        else:
            ctx.write("%s is up to date (version %d)\n" % (ctx.db, old))
    return 0


def cmd_db_version(ctx, pos, opts):
    with ctx.store() as store:
        ctx.write("%d\n" % store.version)


def cmd_db_migrate(ctx, pos, opts):
    from tallybook.storage import LATEST_VERSION

    with ctx.store() as store:
        applied = store.migrate()
        if applied:
            for v in applied:
                ctx.write("applied version %d\n" % v)
        else:
            ctx.write("database is up to date (version %d)\n" % LATEST_VERSION)


def cmd_db_info(ctx, pos, opts):
