# -- reports -----------------------------------------------------------------


def run_report(ctx, kind, ledger, account, opts):
    today = ctx.today()
    if kind == "trial-balance":
        as_of = lib_date(opts["--as-of"]) if "--as-of" in opts else None
        report = reports.trial_balance(ledger, as_of)
    elif kind == "balance-sheet":
        as_of = lib_date(opts["--as-of"]) if "--as-of" in opts else today
        report = reports.balance_sheet(ledger, as_of, opts.get("--convert"), today)
    elif kind == "income-statement":
        period = Period.parse(opts["--period"]) if "--period" in opts else month_of(today)
        report = reports.income_statement(ledger, period, opts.get("--convert"))
    elif kind == "cashflow":
        period = Period.parse(opts["--period"]) if "--period" in opts else month_of(today)
        report = reports.cashflow(ledger, period)
    else:
        period = Period.parse(opts["--period"]) if "--period" in opts else None
        report = reports.register(ledger, account, period, bool(opts.get("--rollup")))
    if opts.get("--json"):
        ctx.write(to_json(report))
    else:
        ctx.write(reports.render_text(report))


def make_report_cmd(kind):
    def handler(ctx, pos, opts):
        with ctx.store() as store:
            ledger = store.ledger()
        run_report(ctx, kind, ledger, pos[0] if pos else None, opts)

    return handler


