    m = re.fullmatch(r"(-?[0-9]{1,18})(?:/(-?[0-9]{1,18}))?", pos[1])
    if m is None:
        raise CliError("invalid ratio %r: expected N or N/D with whole numbers" % pos[1])
    num = int(m.group(1))
    den = int(m.group(2)) if m.group(2) is not None else 1
    ctx.write("%s\n" % Money.parse(pos[0]).scale(num, den))


