    )


def cmd_calc_date_periods(ctx, pos, opts):
    start, end = lib_date(pos[0]), lib_date(pos[1])
    step = pos[2]
    unit = {"week": 7, "month": 31, "quarter": 92, "year": 366}.get(step)
    if unit is not None and end >= start and (end - start).days // unit > 5000:
        raise CliError("too many periods (more than 5000)")
    result = periods(start, end, step)
    if len(result) > 5000:
        raise CliError("too many periods (more than 5000)")
    ctx.write("".join(p.label + "\n" for p in result))


