    end = lib_date(opts["--end"]) if "--end" in opts else None
    count = whole(opts["--count"], "count") if "--count" in opts else None
    if (to - min(frm, start)).days > 40000:
        raise CliError("the span to examine is longer than 40000 days")
    template = Transaction(start, "calc", "", [], (), "*", None)
    rec = recurring_mod.Recurring("calc", pos[0], template, start, end, count)
    ctx.write("".join(format_date(d) + "\n" for d in recurring_mod.occurrences(rec, frm, to)))


