def cmd_calc_rules(ctx, pos, opts):
    rules = parse_rules(read_text(pos[0]))
    fields = {}
    if "--payee" in opts:
        fields["payee"] = opts["--payee"]
    if "--narration" in opts:
        fields["narration"] = opts["--narration"]
    if "--amount" in opts:
        fields["amount"] = Money.parse(opts["--amount"])
    if "--date" in opts:
        fields["date"] = lib_date(opts["--date"])
    rule = rules.match(fields)
    if rule is None:
        ctx.write("no match\n")
        return
    result = rules.apply(fields)
    ctx.write("rule: %d\n" % rule.line)
    for key in ("account", "payee", "narration", "flag"):
        if key in result:
            ctx.write(("%s: %s\n" % (key, result[key])) if result[key] else "%s:\n" % key)
    if "tags" in result:
        ctx.write("tags: %s\n" % ",".join(result["tags"]))


