"""Command handlers and the command table of the `tallybook` command line."""
import os
import re
import sys
from datetime import date, timedelta

from tallybook import budgets as budgets_mod
from tallybook import recurring as recurring_mod
from tallybook import reports
from tallybook.accounts import account_type, parent_path, path_matches, valid_path
from tallybook.cli.main import CliError, Command, UsageError
from tallybook.csvimport import import_csv as csv_import, parse_profile
from tallybook.currency import RateTable
from tallybook.dates import Period, add_months, format_date, last_day, parse_date, periods
from tallybook.errors import TallybookError, ValidationError
from tallybook.export import (
    money_to_dict,
    render_table,
    to_json,
    transaction_to_dict,
    transactions_to_csv,
    transactions_to_json,
)
from tallybook.journal import Journal, JournalError, format_journal, format_transaction, parse_journal
from tallybook.model import Posting, Transaction
from tallybook.money import Money, format_minor
from tallybook.query import parse_query, select
from tallybook.rules import parse_rules

_WHOLE = re.compile(r"(-?)([0-9]{1,18})")
_WEEKDAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]


# -- value helpers -----------------------------------------------------------


def whole(text, what, negative=False):
    m = _WHOLE.fullmatch(text)
    if m is None or (m.group(1) and not negative):
        raise CliError("invalid %s %r: expected a whole number" % (what, text))
    return int(text)


def lib_date(text):
    return parse_date(text)


def read_text(name):
    if name == "-":
        label = "standard input"
        try:
            stream = getattr(sys.stdin, "buffer", None)
            data = stream.read() if stream is not None else sys.stdin.read()
        except OSError as exc:
            raise CliError("cannot read %s: %s" % (label, exc.strerror or exc)) from None
    else:
        label = name
        try:
            with open(name, "rb") as handle:
                data = handle.read()
        except OSError as exc:
            raise CliError("cannot read %s: %s" % (name, exc.strerror or exc)) from None
    if isinstance(data, str):
        return data
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        raise CliError("%s is not valid UTF-8 text" % label) from None


def journal_from(name):
    text = read_text(name)
    try:
        return parse_journal(text)
    except JournalError as exc:
        raise CliError("%s: %s" % ("standard input" if name == "-" else name, exc.message)) from None


def parse_posting(text):
    head, semi, note = text.partition(";")
    parts = re.split(r"[ \t]+", head.strip(" \t"))
    if semi:
        note = note.strip(" \t")
    if len(parts) == 1 and parts[0]:
        return Posting(parts[0], None, note)
    if len(parts) == 3:
        return Posting(parts[0], Money.of(parts[1], parts[2]), note)
    raise CliError("invalid posting %r: expected ACCOUNT or ACCOUNT AMOUNT CURRENCY, then an optional ; note" % text)


def build_template(opts, pos_payee, when):
    postings = [parse_posting(p) for p in opts.get("--posting", [])]
    return Transaction(
        when,
        pos_payee,
        opts.get("--narration", ""),
        postings,
        tuple(opts.get("--tag", [])),
        opts.get("--flag", "*"),
    )


def tx_table(txs):
    if not txs:
        return ""
    rows = [
        [t.id, format_date(t.date), t.flag, t.payee, t.narration, " ".join("#" + g for g in sorted(set(t.tags)))]
        for t in txs
    ]
    return render_table(["Id", "Date", "Flag", "Payee", "Narration", "Tags"], rows, "rlllll")


def account_dict(a):
    return {
        "path": a.path,
        "type": a.type,
        "currency": a.currency,
        "opened": None if a.opened is None else format_date(a.opened),
        "closed": None if a.closed is None else format_date(a.closed),
        "note": a.note,
    }


def month_of(day):
    return Period(day.replace(day=1), day.replace(day=last_day(day.year, day.month)))


# -- init, db, serve ---------------------------------------------------------


def cmd_init(ctx, pos, opts):
    from tallybook.storage import LATEST_VERSION, Store

    fresh = not os.path.exists(ctx.db) or (os.path.isfile(ctx.db) and os.path.getsize(ctx.db) == 0)
    with Store.open(ctx.db, create=True) as store:
        if fresh:
            ctx.write("created %s (version %d)\n" % (ctx.db, store.version))
            return 0
        old = store.version
        if old < LATEST_VERSION:
            store.migrate()
            ctx.write("migrated %s from version %d to %d\n" % (ctx.db, old, store.version))
        else:
            ctx.write("%s is up to date (version %d)\n" % (ctx.db, old))
    return 0


def cmd_db_version(ctx, pos, opts):
    with ctx.store() as store:
        ctx.write("%d\n" % store.version)


def cmd_db_migrate(ctx, pos, opts):
    from tallybook.storage import LATEST_VERSION

    with ctx.store() as store:
        applied = store.migrate()
        if applied:
            for v in applied:
                ctx.write("applied version %d\n" % v)
        else:
            ctx.write("database is up to date (version %d)\n" % LATEST_VERSION)


def cmd_db_info(ctx, pos, opts):
    with ctx.store() as store:
        info = store.info()
    if opts.get("--json"):
        ctx.write(to_json(info))
        return
    for key in ("path", "version", "accounts", "transactions", "postings", "rates", "budgets", "recurring"):
        ctx.write("%s: %s\n" % (key, info[key]))


def cmd_db_check(ctx, pos, opts):
    with ctx.store() as store:
        problems = store.check()
    if not problems:
        ctx.write("ok\n")
        return 0
    ctx.write("".join(p + "\n" for p in problems))
    return 1


def cmd_db_backup(ctx, pos, opts):
    with ctx.store() as store:
        store.backup(pos[0])
    ctx.write("backed up to %s\n" % pos[0])


def cmd_serve(ctx, pos, opts):
    from tallybook.api.server import serve

    host = opts.get("--host", "127.0.0.1")
    port = whole(opts["--port"], "port") if "--port" in opts else 8765
    if port > 65535:
        raise CliError("invalid port %r: the largest is 65535" % opts["--port"])
    with ctx.store() as store:
        store.info()
    return serve(ctx.db, host=host, port=port, today=ctx.today_opt)


# -- accounts ----------------------------------------------------------------


def cmd_account_add(ctx, pos, opts):
    opened = lib_date(opts["--open"]) if "--open" in opts else None
    with ctx.store() as store:
        store.add_account(pos[0], None, opts.get("--currency"), opened, opts.get("--note", ""))
    ctx.write("added account %s\n" % pos[0])


def cmd_account_list(ctx, pos, opts):
    with ctx.store() as store:
        accounts = store.accounts(
            opts.get("--type"), opts.get("--under"), opts.get("--currency"), include_closed=not opts.get("--open-only")
        )
    if opts.get("--json"):
        ctx.write(to_json([account_dict(a) for a in accounts]))
    elif accounts:
        rows = [
            [
                a.path,
                a.type,
                a.currency or "",
                "" if a.opened is None else format_date(a.opened),
                "" if a.closed is None else format_date(a.closed),
                a.note,
            ]
            for a in accounts
        ]
        ctx.write(render_table(["Account", "Type", "Currency", "Opened", "Closed", "Note"], rows))


def cmd_account_show(ctx, pos, opts):
    with ctx.store() as store:
        account = store.get_account(pos[0])
        balance = store.ledger().balance(pos[0])
    money = [balance[c] for c in sorted(balance)]
    if opts.get("--json"):
        data = account_dict(account)
        data["balance"] = [money_to_dict(m) for m in money]
        ctx.write(to_json(data))
        return
    d = account_dict(account)
    lines = [
        "path: %s" % account.path,
        "type: %s" % account.type,
        "currency: %s" % (account.currency or "any"),
        "opened: %s" % (d["opened"] or "none"),
        "closed: %s" % (d["closed"] or "none"),
        ("note: %s" % account.note) if account.note else "note:",
        "balance: %s" % (", ".join(str(m) for m in money) if money else "none"),
    ]
    ctx.write("".join(line + "\n" for line in lines))


def cmd_account_close(ctx, pos, opts):
    on = lib_date(opts["--on"]) if "--on" in opts else ctx.today()
    with ctx.store() as store:
        store.close_account(pos[0], on)
    ctx.write("closed account %s on %s\n" % (pos[0], format_date(on)))


# -- transactions ------------------------------------------------------------


def cmd_tx_add(ctx, pos, opts):
    when = lib_date(opts["--date"]) if "--date" in opts else ctx.today()
    tx = build_template(opts, pos[0], when)
    with ctx.store() as store:
        stored = store.add_transaction(tx)
    if opts.get("--json"):
        ctx.write(to_json(transaction_to_dict(stored)))
    else:
        ctx.write("added transaction %d\n" % stored.id)


def _listing(ctx, txs, opts):
    if opts.get("--json"):
        ctx.write(to_json([transaction_to_dict(t) for t in txs]))
    else:
        ctx.write(tx_table(txs))


def _paging(opts):
    limit = whole(opts["--limit"], "limit") if "--limit" in opts else None
    offset = whole(opts["--offset"], "offset") if "--offset" in opts else 0
    return limit, offset


def cmd_tx_list(ctx, pos, opts):
    limit, offset = _paging(opts)
    with ctx.store() as store:
        txs = store.transactions(opts.get("--query"), limit, offset)
    _listing(ctx, txs, opts)


def cmd_query(ctx, pos, opts):
    limit, offset = _paging(opts)
    with ctx.store() as store:
        if opts.get("--count"):
            ctx.write("%d\n" % store.count_transactions(pos[0]))
            return
        txs = store.transactions(pos[0], limit, offset)
    _listing(ctx, txs, opts)


def cmd_tx_show(ctx, pos, opts):
    tid = whole(pos[0], "transaction id")
    with ctx.store() as store:
        tx = store.get_transaction(tid)
    if opts.get("--json"):
        ctx.write(to_json(transaction_to_dict(tx)))
    else:
        ctx.write("; id %d\n" % tx.id + format_transaction(tx))


def cmd_tx_delete(ctx, pos, opts):
    tid = whole(pos[0], "transaction id")
    with ctx.store() as store:
        store.delete_transaction(tid)
    ctx.write("deleted transaction %d\n" % tid)


def cmd_export(ctx, pos, opts):
    fmt = opts.get("--format", "csv")
    if fmt not in ("csv", "json", "journal"):
        raise CliError("unknown export format %r: expected csv, json or journal" % fmt)
    if fmt == "journal" and "--query" in opts:
        raise CliError("export --format journal exports the whole book and takes no --query")
    with ctx.store() as store:
        if fmt == "journal":
            ctx.write(format_journal(store.journal()))
        elif fmt == "csv":
            ctx.write(transactions_to_csv(store.transactions(opts.get("--query"))))
        else:
            ctx.write(transactions_to_json(store.transactions(opts.get("--query"))))


