def cmd_import(ctx, pos, opts):
    if ("--profile" in opts) == ("--profile-file" in opts):
        raise UsageError("give exactly one of --profile and --profile-file")
    text = read_text(pos[0])
    if "--profile-file" in opts:
        profile = parse_profile(read_text(opts["--profile-file"]))
    with ctx.store() as store:
        if "--profile" in opts:
            profile = parse_profile(store.profile_text(opts["--profile"]))
        outcome = store.import_csv(text, profile, apply_rules=not opts.get("--no-rules"))
    if outcome.errors:
        raise CliError(
            "%d rows could not be imported, nothing was imported" % len(outcome.errors),
            ["row %d: %s" % (n, msg) for n, msg in outcome.errors],
        )
    ctx.write("imported %d transactions, %d duplicates\n" % (len(outcome.added), len(outcome.duplicates)))


