def _recurring_dict(rec, through):
    t = rec.template
    return {
        "name": rec.name,
        "schedule": str(rec.schedule),
        "start": format_date(rec.start),
        "end": None if rec.end is None else format_date(rec.end),
        "count": rec.count,
        "materialized_through": None if through is None else format_date(through),
        "template": {
            "payee": t.payee,
            "narration": t.narration,
            "flag": t.flag,
            "tags": sorted(set(t.tags)),
            "postings": [
                {"account": p.account, "amount": money_to_dict(p.amount), "note": p.note} for p in t.postings
            ],
        },
    }


def cmd_recurring_list(ctx, pos, opts):
