        items = [(rec, store.materialized_through(rec.name)) for rec in store.recurring()]
    if opts.get("--json"):
        ctx.write(to_json([_recurring_dict(r, t) for r, t in items]))
    elif items:
        rows = [
            [
                r.name,
                str(r.schedule),
                format_date(r.start),
                "" if r.end is None else format_date(r.end),
                "" if r.count is None else r.count,
                "" if t is None else format_date(t),
                r.template.payee,
            ]
            for r, t in items
        ]
        ctx.write(render_table(["Name", "Schedule", "Start", "End", "Count", "Through", "Payee"], rows))


