    ctx.write("%s %s\n" % (format_minor(minor, pos[1]), pos[1]))


def cmd_calc_money_add(ctx, pos, opts):
    ctx.write("%s\n" % (Money.parse(pos[0]) + Money.parse(pos[1])))


def cmd_calc_money_sub(ctx, pos, opts):
    ctx.write("%s\n" % (Money.parse(pos[0]) - Money.parse(pos[1])))


def cmd_calc_money_scale(ctx, pos, opts):
    m = re.fullmatch(r"(-?[0-9]{1,18})(?:/(-?[0-9]{1,18}))?", pos[1])
    if m is None:
        raise CliError("invalid ratio %r: expected N or N/D with whole numbers" % pos[1])
    num = int(m.group(1))
    den = int(m.group(2)) if m.group(2) is not None else 1
    ctx.write("%s\n" % Money.parse(pos[0]).scale(num, den))


def cmd_calc_money_allocate(ctx, pos, opts):
    weights = [whole(w, "weight") for w in pos[1:]]
    for part in Money.parse(pos[0]).allocate(weights):
        ctx.write("%s\n" % part)


def cmd_calc_money_convert(ctx, pos, opts):
    m = Money.parse(pos[0])
    table = RateTable()
    day = date(2000, 1, 1)
    table.set(m.currency, pos[1], pos[2], day)
    ctx.write("%s\n" % table.convert(m, pos[1], day))


def cmd_calc_date_parse(ctx, pos, opts):
