_REPORT_KINDS = ("trial-balance", "balance-sheet", "income-statement", "cashflow", "register")


def cmd_calc_report(ctx, pos, opts):
    kind = pos[0]
    if kind not in _REPORT_KINDS:
        raise UsageError("unknown report kind '%s'" % kind)
    account = pos[1] if len(pos) > 1 else None
    if kind == "register" and account is None:
        raise UsageError("missing argument: ACCOUNT")
    ledger = journal_ledger(opts["--journal"])
    run_report(ctx, kind, ledger, account, opts)


def cmd_calc_csv(ctx, pos, opts):
    profile = parse_profile(read_text(pos[0]))
    rules = parse_rules(read_text(opts["--rules"])) if "--rules" in opts else None
    result = csv_import(read_text(pos[1]), profile, rules, ())
    if result.errors:
        raise CliError_lines(["row %d: %s" % (n, msg) for n, msg in result.errors])
    ctx.write(format_journal(Journal([], [], result.transactions)))


class CliError_lines(CliError):
    """A refusal whose stderr is exactly the given lines, without the `tallybook: ` lead."""

    def __init__(self, lines):
        super().__init__(lines[0], lines[1:])


# -- the table ---------------------------------------------------------------

_J = ("--json",)


def _cmd(name, usage, handler, **kw):
    return Command(name, "usage: tallybook " + usage + "\n", handler, **kw)


def build_tree():
    t = {}
    t["init"] = _cmd("init", "init", cmd_init)
    t["serve"] = _cmd("serve", "serve [--host HOST] [--port N]", cmd_serve, values=("--host", "--port"))
    t["db"] = {
        "version": _cmd("db version", "db version", cmd_db_version),
        "migrate": _cmd("db migrate", "db migrate", cmd_db_migrate),
        "info": _cmd("db info", "db info [--json]", cmd_db_info, flags=_J),
        "check": _cmd("db check", "db check", cmd_db_check),
        "backup": _cmd("db backup", "db backup DEST", cmd_db_backup, pos=["DEST"]),
    }
    t["account"] = {
        "add": _cmd(
            "account add",
            "account add PATH [--currency CUR] [--open DATE] [--note TEXT]",
            cmd_account_add,
            pos=["PATH"],
            values=("--currency", "--open", "--note"),
        ),
        "list": _cmd(
            "account list",
            "account list [--type TYPE] [--under PATH] [--currency CUR] [--open-only] [--json]",
            cmd_account_list,
            values=("--type", "--under", "--currency"),
            flags=("--open-only", "--json"),
        ),
        "show": _cmd("account show", "account show PATH [--json]", cmd_account_show, pos=["PATH"], flags=_J),
        "close": _cmd(
            "account close", "account close PATH [--on DATE]", cmd_account_close, pos=["PATH"], values=("--on",)
        ),
    }
    t["tx"] = {
        "add": _cmd(
            "tx add",
            "tx add PAYEE [--date DATE] [--narration TEXT] [--flag F] [--tag TAG]... [-p POSTING]... [--json]",
            cmd_tx_add,
            pos=["PAYEE"],
            values=("--date", "--narration", "--flag", "--tag", "--posting"),
            repeat=("--tag", "--posting"),
            flags=_J,
        ),
        "list": _cmd(
            "tx list",
            "tx list [--query QUERY] [--limit N] [--offset N] [--json]",
            cmd_tx_list,
            values=("--query", "--limit", "--offset"),
            flags=_J,
        ),
        "show": _cmd("tx show", "tx show ID [--json]", cmd_tx_show, pos=["ID"], flags=_J),
        "delete": _cmd("tx delete", "tx delete ID", cmd_tx_delete, pos=["ID"]),
    }
    t["query"] = _cmd(
        "query",
        "query QUERY [--limit N] [--offset N] [--json] [--count]",
        cmd_query,
        pos=["QUERY"],
        values=("--limit", "--offset"),
        flags=("--json", "--count"),
    )
    t["export"] = _cmd(
        "export",
        "export [--format csv|json|journal] [--query QUERY]",
        cmd_export,
        values=("--format", "--query"),
    )
    t["journal"] = {
        "export": _cmd("journal export", "journal export", cmd_journal_export),
        "import": _cmd("journal import", "journal import FILE", cmd_journal_import, pos=["FILE"]),
    }
    t["import"] = _cmd(
        "import",
        "import FILE (--profile NAME | --profile-file FILE) [--no-rules]",
        cmd_import,
        pos=["FILE"],
        values=("--profile", "--profile-file"),
        flags=("--no-rules",),
    )
    t["profile"] = {
        "add": _cmd("profile add", "profile add NAME FILE", cmd_profile_add, pos=["NAME", "FILE"]),
        "list": _cmd("profile list", "profile list [--json]", cmd_profile_list, flags=_J),
        "show": _cmd("profile show", "profile show NAME", cmd_profile_show, pos=["NAME"]),
        "remove": _cmd("profile remove", "profile remove NAME", cmd_profile_remove, pos=["NAME"]),
    }
    t["rules"] = {
        "set": _cmd("rules set", "rules set FILE", cmd_rules_set, pos=["FILE"]),
        "show": _cmd("rules show", "rules show", cmd_rules_show),
    }
    t["rate"] = {
        "set": _cmd(
            "rate set", "rate set FROM TO RATE [--on DATE]", cmd_rate_set, pos=["FROM", "TO", "RATE"], values=("--on",)
        ),
        "list": _cmd("rate list", "rate list [--json]", cmd_rate_list, flags=_J),
        "remove": _cmd(
            "rate remove", "rate remove FROM TO [--on DATE]", cmd_rate_remove, pos=["FROM", "TO"], values=("--on",)
        ),
    }
    t["budget"] = {
        "add": _cmd(
            "budget add",
            "budget add PATTERN AMOUNT [--per KIND] [--start DATE]",
            cmd_budget_add,
            pos=["PATTERN", "AMOUNT"],
            values=("--per", "--start"),
        ),
        "list": _cmd("budget list", "budget list [--json]", cmd_budget_list, flags=_J),
        "remove": _cmd(
            "budget remove", "budget remove PATTERN [--per KIND]", cmd_budget_remove, pos=["PATTERN"], values=("--per",)
        ),
        "status": _cmd(
            "budget status",
            "budget status [--period PERIOD] [--json]",
            cmd_budget_status,
            values=("--period",),
            flags=_J,
        ),
    }
    t["recurring"] = {
        "add": _cmd(
            "recurring add",
            "recurring add NAME SCHEDULE PAYEE [--start DATE] [--end DATE] [--count N] [--narration TEXT] "
            "[--flag F] [--tag TAG]... [-p POSTING]...",
            cmd_recurring_add,
            pos=["NAME", "SCHEDULE", "PAYEE"],
            values=("--start", "--end", "--count", "--narration", "--flag", "--tag", "--posting"),
            repeat=("--tag", "--posting"),
        ),
        "list": _cmd("recurring list", "recurring list [--json]", cmd_recurring_list, flags=_J),
        "remove": _cmd("recurring remove", "recurring remove NAME", cmd_recurring_remove, pos=["NAME"]),
        "materialize": _cmd(
            "recurring materialize",
            "recurring materialize [--upto DATE] [--json]",
            cmd_recurring_materialize,
            values=("--upto",),
            flags=_J,
        ),
    }
    t["report"] = {
        "trial-balance": _cmd(
            "report trial-balance",
            "report trial-balance [--as-of DATE] [--json]",
            make_report_cmd("trial-balance"),
            values=("--as-of",),
            flags=_J,
        ),
        "balance-sheet": _cmd(
            "report balance-sheet",
            "report balance-sheet [--as-of DATE] [--convert CUR] [--json]",
            make_report_cmd("balance-sheet"),
            values=("--as-of", "--convert"),
            flags=_J,
        ),
        "income-statement": _cmd(
            "report income-statement",
            "report income-statement [--period PERIOD] [--convert CUR] [--json]",
            make_report_cmd("income-statement"),
            values=("--period", "--convert"),
            flags=_J,
        ),
        "cashflow": _cmd(
            "report cashflow",
            "report cashflow [--period PERIOD] [--json]",
            make_report_cmd("cashflow"),
            values=("--period",),
            flags=_J,
        ),
        "register": _cmd(
