import re
files=["money","currency","dates","accounts","ledger","export"]
for f in files:
    p=f"tallybook/{f}.py"
    out=[]
    changed=False
    for line in open(p).read().split("\n"):
        if "%r" in line and "% (" in line and "__repr__" not in line and 'Money(%d' not in line:
            m=re.match(r'^(.*?"[^"]*"\s*)% \((.*)\)(\s*from None)?$',line)
            if m:
                head,args,tail=m.group(1),m.group(2),m.group(3) or ""
                fmt=re.search(r'"([^"]*)"',head).group(1)
                holders=re.findall(r'%[rsd]',fmt)
                items=[a.strip() for a in args.rstrip(",").split(",")]
                if len(holders)==len(items):
                    new=[f"raw({it})" if h=="%r" else it for h,it in zip(holders,items)]
                    tup=", ".join(new)+("," if len(new)==1 else "")
                    line=f"{head}% ({tup}){tail}"
                    changed=True
        out.append(line)
    s="\n".join(out)
    if changed:
        # ensure import
        if "from tallybook.errors import" in s:
            s=re.sub(r"from tallybook.errors import ([^\n]+)",lambda m: "from tallybook.errors import "+m.group(1)+", raw" if "raw" not in m.group(1) else m.group(0),s,count=1)
        open(p,"w").write(s)
        print("patched",f)
EOF
